`timescale 1ns/1ps module tb_audio_playback_control;  reg clk=0,rst=1,key_n=1,run_switch=0,fifo_empty=1; wire [1:0] player_mode; wire reader_enable,reader_reset;  always #5 clk=~clk;  audio_playback_control #(.CLK_FREQ_HZ(1000),.DEBOUNCE_MS(2)) dut(.clk(clk),.rst(rst),.play_pause_key_n(key_n),.run_switch(run_switch),.fifo_empty_async(fifo_empty),.player_mode(player_mode),.reader_enable(reader_enable),.reader_reset(reader_reset));  task settle;begin repeat(8)@(posedge clk);end endtask  task press_key;begin key_n=0;settle;key_n=1;settle;end endtask  initial begin repeat(3)@(posedge clk);rst=0;run_switch=1;settle;if(player_mode!==2'd1)$fatal(1,"start");press_key;if(player_mode!==2'd2)$fatal(1,"pause");press_key;if(player_mode!==2'd1)$fatal(1,"resume");run_switch=0;settle;if(player_mode!==2'd0||!reader_reset)$fatal(1,"stop");run_switch=1;fifo_empty=0;settle;if(player_mode!==2'd0)$fatal(1,"drain");fifo_empty=1;settle;if(player_mode!==2'd1)$fatal(1,"restart");$display("PASS audio playback control");$finish;end endmodule
